package com.atlasiq.security;
import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.util.stream.Stream;
@ApplicationScoped public class ContainerPackageParser {private static final Pattern FROM=Pattern.compile("(?im)^FROM\\s+([^\\s]+)");public List<QirNode> parse(Path root){List<QirNode> out=new ArrayList<>();try(Stream<Path>s=Files.walk(root,6)){s.filter(p->p.getFileName().toString().startsWith("Dockerfile")).forEach(p->{try{Matcher m=FROM.matcher(Files.readString(p));while(m.find()){String image=m.group(1);out.add(new QirNode("container-image:"+image,"container-base-image",image,"oci",Map.of("evidenceFile",root.relativize(p).toString(),"vulnerabilityScanRequired",true)));}}catch(Exception ignored){}});}catch(Exception ignored){}return List.copyOf(out);}}
